def countKthRoots(l, r, k):
    def power_at_least(x, limit):
        # Return True if x ** k >= limit, multiplying with an early exit
        p = 1
        for _ in range(k):
            p *= x
            if p >= limit:
                return True
        return p >= limit

    def smallest_x(limit):
        # Binary search for the smallest x >= 0 with x ** k >= limit
        lo, hi = 0, 10 ** 9 + 1
        while lo < hi:
            mid = (lo + hi) // 2
            if power_at_least(mid, limit):
                hi = mid
            else:
                lo = mid + 1
        return lo

    # Bases x with l <= x**k <= r are exactly smallest_x(l) <= x < smallest_x(r + 1)
    return smallest_x(r + 1) - smallest_x(l)
